//! Same binary, real GPU, serial versus two-frame producer/encoder overlap.
use kronello_audio::{AudioSourceMode, ClippingPolicy};
use kronello_gpu::GpuContext;
use kronello_media::*;
use kronello_model::{DocumentObject, Project};
use kronello_render::*;
use kronello_time::{FrameRate, Time, TimeRange};
use serde_json::json;
use std::{path::PathBuf, time::Instant};
fn snapshot(temporal: bool) -> RenderSnapshot {
    let mut document: Project =
        serde_json::from_str(include_str!("../../examples/m1-demo.project.json")).unwrap();
    let DocumentObject::Known(composition) = &mut document.compositions[0] else {
        panic!()
    };
    composition.nodes.truncate(1);
    composition.root_nodes.truncate(1);
    let id = composition.id;
    document.texts.clear();
    RenderSnapshot::new(
        &document,
        id,
        1,
        RenderProfile {
            temporal: temporal.then_some(TemporalSettings {
                frame_rate: FrameRate::new(24, 1).unwrap(),
                shutter_angle: Time::new(180, 1).unwrap(),
                shutter_phase: Time::new(-1, 4).unwrap(),
                samples: 3,
                cut_policy: CutPolicy::AvoidCrossing,
            }),
            ..RenderProfile::default()
        },
    )
    .unwrap()
}
fn export_snapshot(render: &RenderSnapshot, profile: MovieProfile) -> AvExportSnapshot {
    if profile == MovieProfile::ProResPcm24 {
        AvExportSnapshot::with_audio(render, AudioSourceMode::Silence, vec![])
    } else {
        AvExportSnapshot::with_movie_profile(render, AudioSourceMode::Silence, vec![], profile)
    }
    .unwrap()
}
fn main() {
    let directory = PathBuf::from(std::env::args().nth(1).unwrap());
    std::fs::create_dir(&directory).unwrap();
    let runtime = MediaRuntime::load().unwrap();
    let gpu = GpuContext::new().unwrap();
    let render = snapshot(true);
    let av = export_snapshot(&render, MovieProfile::DnxhrHqxMovPcm24V1);
    let mut trials = Vec::new();
    for iteration in 0..22 {
        let modes = if iteration % 2 == 0 {
            [VideoPipelineMode::Serial, VideoPipelineMode::TwoFrames]
        } else {
            [VideoPipelineMode::TwoFrames, VideoPipelineMode::Serial]
        };
        for mode in modes {
            let output = directory.join(format!("{mode:?}-{iteration}.mov"));
            let request = AvExportRequest {
                output: output.clone(),
                range: TimeRange::new(Time::new(1, 2).unwrap(), Time::ONE).unwrap(),
                frame_rate: FrameRate::new(24, 1).unwrap(),
                region: OutputRegion { origin: [0.0; 2], extent: [64.0,32.0], pixels: [640,360] },
                background: [0.0;3], clipping: ClippingPolicy::Reject,
                chapters: ChapterPolicy::Omit, outputs: Vec::new(),
            };
            let selected = runtime.clone().with_video_pipeline_mode(mode);
            let mut checkpoints = Vec::new();
            let start = Instant::now();
            let report = selected.export_delivery_with_checkpoint(&[&av], &directory.join("unused.kronello"), &[], &gpu, &request, &mut |n| { checkpoints.push(n); Ok(()) }).unwrap();
            let wall_ms = start.elapsed().as_secs_f64()*1000.0;
            let transfers:Vec<_> = report.frames.iter().map(|f| &f.transfer_stats).collect();
            trials.push(json!({"iteration":iteration,"mode":format!("{mode:?}"),"wall_ms":wall_ms,"path":output,"sha256":content_hash(&output).unwrap(),"checkpoints":checkpoints,"sample_range":report.sample_range,"transfers":transfers}));
        }
    }
    println!("{}",serde_json::to_string_pretty(&json!({"quiet_host":false,"shared_gpu_context":true,"alternating_pair_order":true,"cold_pairs":1,"warm_pairs":21,"scope":"DNxHR HQX 640x360, 12 frames, 3 shutter samples, PCM24 silence; same binary, shared GPU, same worker pipeline; encoder runtime load and export included, GPU creation/hash excluded","capabilities":runtime.capabilities(),"trials":trials})).unwrap());
}
